// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        amount = bound(amount, 1, 1 ether);
        vm.assume(receiver != address(c));

        vm.deal(address(c), amount);

        uint256 balanceBefore = address(c).balance;

        vm.prank(address(this));
        c.sendTo(receiver, amount);

        uint256 balanceAfter = address(c).balance;

        assertTrue(balanceBefore - balanceAfter == amount);
    }
}
